function createSitemapRoutes(config) {
  const app = new Hono2;
  app.get("/sitemap.xml", async (c) => {
    const sql2 = getClient();
    const domain = config.site.domain.replace(/\/$/, "");
    const urls = [];
    urls.push({ loc: domain, lastmod: new Date().toISOString().split("T")[0] });
    for (const collection of config.collections) {
      const tableName = collectionToTableName(collection.name);
      const hasSlug = "slug" in collection.fields;
      const rows = await sql2.unsafe(`SELECT ${hasSlug ? "slug," : ""} updated_at FROM "${tableName}" WHERE status = 'published' ORDER BY updated_at DESC`);
      for (const row of rows) {
        const r = row;
        const path = hasSlug ? `/${collection.name}/${r.slug}` : `/${collection.name}/${r.id}`;
        const lastmod = r.updated_at ? new Date(r.updated_at).toISOString().split("T")[0] : new Date().toISOString().split("T")[0];
        urls.push({ loc: `${domain}${path}`, lastmod });
      }
    }
    const xml = `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls.map((u) => `  <url>
    <loc>${escapeXml(u.loc)}</loc>
    <lastmod>${u.lastmod}</lastmod>
  </url>`).join(`
`)}
</urlset>`;
    c.header("Content-Type", "application/xml");
    return c.body(xml);
  });
  return app;
}
function escapeXml(str) {
  return str.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&apos;");
}

