// src/api/graphql/schema-builder.ts
function fieldToGraphQLType(field) {
  switch (field.type) {
    case "text":
    case "textarea":
    case "slug":
    case "url":
    case "select":
    case "colour":
      return field.required ? "String!" : "String";
    case "richText":
    case "seoBlock":
    case "blocks":
    case "multiSelect":
    case "array":
      return "JSON";
    case "number":
      return field.required ? "Float!" : "Float";
    case "boolean":
      return field.required ? "Boolean!" : "Boolean";
    case "datetime":
      return "String";
    case "media":
    case "relation":
      return "ID";
  }
}
function capitalize(str) {
  return str.charAt(0).toUpperCase() + str.slice(1);
}
function buildGraphQLSchema(config) {
  const types3 = [];
  const queries = [];
  types3.push(`scalar JSON`);
  types3.push("");
  for (const collection of config.collections) {
    const typeName = capitalize(collection.name);
    const fields2 = [
      "  id: ID!",
      "  status: String!",
      "  createdAt: String!",
      "  updatedAt: String!",
      "  publishedAt: String"
    ];
    const systemFields = new Set(["status", "publishedAt", "createdAt", "updatedAt"]);
    for (const [fieldName, field] of Object.entries(collection.fields)) {
      if (systemFields.has(fieldName))
        continue;
      fields2.push(`  ${fieldName}: ${fieldToGraphQLType(field)}`);
    }
    types3.push(`type ${typeName} {`);
    types3.push(fields2.join(`
`));
    types3.push("}");
    types3.push("");
    types3.push(`type ${typeName}List {`);
    types3.push(`  data: [${typeName}!]!`);
    types3.push("  total: Int!");
    types3.push("  page: Int!");
    types3.push("  limit: Int!");
    types3.push("  totalPages: Int!");
    types3.push("}");
    types3.push("");
    queries.push(`  ${collection.name}(id: ID!): ${typeName}`);
    queries.push(`  ${collection.name}BySlug(slug: String!): ${typeName}`);
    queries.push(`  ${collection.name}List(page: Int, limit: Int, status: String, sort: String, order: String): ${typeName}List`);
  }
  types3.push("type Query {");
  types3.push(queries.join(`
`));
  types3.push("}");
  return types3.join(`
`);
}

// src/api/graphql/resolvers.ts
function buildResolvers(config) {
  const Query2 = {};
  for (const collection of config.collections) {
    const tableName = collectionToTableName(collection.name);
    Query2[collection.name] = async (_, args) => {
      const sql2 = getClient();
      const rows = await sql2.unsafe(`SELECT * FROM "${tableName}" WHERE id = $1 LIMIT 1`, [args.id]);
      return rows[0] || null;
    };
    Query2[`${collection.name}BySlug`] = async (_, args) => {
      const sql2 = getClient();
      const rows = await sql2.unsafe(`SELECT * FROM "${tableName}" WHERE slug = $1 LIMIT 1`, [args.slug]);
      return rows[0] || null;
    };
    Query2[`${collection.name}List`] = async (_, args) => {
      const sql2 = getClient();
      const page = args.page || 1;
      const limit = Math.min(args.limit || 20, 100);
      const offset = (page - 1) * limit;
      const sortCol = args.sort ? fieldToColumnName(args.sort) : "created_at";
      const order = args.order === "asc" ? "ASC" : "DESC";
      const conditions = [];
      const params = [];
      if (args.status) {
        conditions.push(`status = $${params.length + 1}`);
        params.push(args.status);
      }
      const whereClause = conditions.length > 0 ? `WHERE ${conditions.join(" AND ")}` : "";
      const countResult = await sql2.unsafe(`SELECT COUNT(*) as total FROM "${tableName}" ${whereClause}`, params);
      const total = parseInt(countResult[0].total, 10);
      const rows = await sql2.unsafe(`SELECT * FROM "${tableName}" ${whereClause} ORDER BY "${sortCol}" ${order} LIMIT ${limit} OFFSET ${offset}`, params);
      return {
        data: rows,
        total,
        page,
        limit,
        totalPages: Math.ceil(total / limit)
      };
    };
  }
  return { Query: Query2 };
}

// src/api/server.ts
function createServer(config) {
  const app = new Hono2;
  app.use("*", corsMiddleware);
  app.onError(errorHandler2);
  const apiRouter = createApiRouter(config);
  app.route("/", apiRouter);
  const yoga = createYoga({
    schema: createSchema({
      typeDefs: buildGraphQLSchema(config),
      resolvers: buildResolvers(config)
    }),
    graphqlEndpoint: "/api/graphql",
    landingPage: false
  });
  app.on(["GET", "POST"], "/api/graphql", async (c) => {
    const response = await yoga.handle(c.req.raw);
    return response;
  });
  return app;
}
function startServer(config, port = 3000) {
  const app = createServer(config);
  console.log(`CMS API server starting on http://localhost:${port}`);
  console.log(`  REST API: http://localhost:${port}/api`);
  console.log(`  GraphQL:  http://localhost:${port}/api/graphql`);
  console.log(`  Health:   http://localhost:${port}/api/health`);
  Bun.serve({
    fetch: app.fetch,
    port
  });
}
